-- Rifts World Book 8: Japan - tech gear: 115 new rows. See
-- apps/character-creator/docs/surveys/japan.md, step 4.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/add-a-japan-tech-gear.sql
--
-- TEXT LAYER, page_offset +1. Extracted by three book-extract-workers and
-- checked row by row by two book-reconcile passes. Printed 109 is a welded page
-- and printed 122-128 interleave their stat blocks; both were read off renders.
--
-- WHAT IS HERE: cybernetics and bionics (printed 109-113), the high-tech
-- weapons, vibro-blades, gear and explosives of ArmaTech and H-Brand (114-131),
-- and the body armor and packs (181-186). The five palm energy generators are a
-- row each, as the book prices them separately.
--
-- NOT HERE, because the catalog already holds this book's figures from an
-- earlier Rifts book: the Bio-Comp self-monitoring system, internal
-- comp-calculator and laser beam eye (Triax); the hand-held flare, parachute
-- flare and stun/flash grenade (Triax); and the mini, light, medium and heavy
-- torpedoes (Underseas printed 117). This book prints the mini torpedo at
-- 1D4x10 M.D. where Underseas prints 1D6x10; the Underseas row stands.
--
-- M.D.C. IS STORED ONLY WHERE THE ITEM PRINTS ONE. Printed 115 gives typical
-- figures for a class of weapon (15 for a pistol or vibro-blade, 30-40 for a
-- rifle, about 100 for a giant weapon); those are not copied onto items that
-- print none. The H-20, H-30 and H-25 knock-offs print only a price, so their
-- damage is NULL rather than inferred from the ArmaTech original.

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book) VALUES
('snarls-sensor-system', 'SNARLS Sensor System', 'rifts', 'gear', 1.2, 125000, '125,000 cr; military and police Special Forces only, not on Black Market or from H-Brand', NULL, 0, '200 ft (61 m) in a 120 degree arc; about 50% error out to roughly 500 ft', NULL, NULL, NULL, NULL, 6, 'Rifle-scope-style sensor that detects distance, motion, heat, radiation, scent and bio-patterns (PPE 80+), to reveal supernatural and invisible beings. It feeds a belt mini-computer that projects data to the helmet HUD and can identify 2000 creatures. Invisible creatures win initiative on the first action.', 'Rifts World Book 8: Japan p.116'),
('pr-1-standard-backpack', 'PR-1 Standard Backpack', 'rifts', 'gear', NULL, 5000, '5000 cr', NULL, 0, NULL, 'Survival kit: knife, water tablets, 1 qt canteen, medical kit, 5 days rations; standard pack also lists 3 weeks freeze-dried rations, stove, camo uniform, IR flashlight, fishing kit, thermal poncho/tent, 200-gallon water purifier', NULL, NULL, NULL, 20, 'Standard issue pack of the Republic''s armed forces, with a homing beacon and an electromagnetic pad that locks to body armor (combined P.S. 50 to pull it off). One large and three small compartments.', 'Rifts World Book 8: Japan p.116'),
('pr-2-radio-operator-pack', 'PR-2 Radio Operator Pack', 'rifts', 'gear', NULL, 6500, '6500 cr', NULL, 0, 'helmet radio extended to 50 miles (80 km)', 'Radio, tool kit, weapon cleaning kit, spare rifle parts, 10 standard E-clips, 1 Satchel Charge, 2 fragmentation grenades', NULL, NULL, NULL, 20, 'Backpack with a carrier-wave amplifier that extends the helmet radio to 50 miles, plus radio, tools and spare E-clips and explosives.', 'Rifts World Book 8: Japan p.117'),
('pr-3-rail-gunner-s-pack', 'PR-3 Rail Gunner''s Pack', 'rifts', 'gear', NULL, 4500, '4500 cr for a fully loaded PR-3', NULL, 0, NULL, 'Main compartment holds an AT-600 rail gun ammo drum (heavy drum: 2400 rounds, 80 bursts per the AT-600 entry); basic survival gear in outer pockets', NULL, NULL, NULL, 20, 'Rail gunner''s pack built to carry an AT-600 ammunition drum, with only basic survival gear in the outer pockets.', 'Rifts World Book 8: Japan p.117'),
('armatech-h-brand-pistol-e-clip', 'ArmaTech/H-Brand Pistol E-Clip', 'rifts', 'gear', NULL, 6500, '6500 cr undamaged and fully charged; recharge about 1200-2000', NULL, 0, NULL, '10 to 20 shots (pistols)', NULL, NULL, NULL, NULL, 'Hand-loaded energy magazine shared by ArmaTech and H-Brand pistols (H-Brand''s is a cheaper copy). Also powers most bionic and cybernetic weapons and fits CS, Northern Gun, Wilk''s and New Navy weapons.', 'Rifts World Book 8: Japan p.117'),
('armatech-h-brand-rifle-e-clip', 'ArmaTech/H-Brand Rifle E-Clip', 'rifts', 'gear', NULL, 10000, '10,000 cr new; recharge about 3000', NULL, 0, NULL, '20 to 30 shots', NULL, NULL, NULL, NULL, 'Larger energy magazine, identical and interchangeable between ArmaTech and H-Brand. Too big for the smaller pistols.', 'Rifts World Book 8: Japan p.117'),
('armatech-energy-canister', 'ArmaTech Energy Canister', 'rifts', 'gear', NULL, 21000, '21,000 cr; recharge about 5500; mainly military, very hard to find on the Black Market', NULL, 0, NULL, '30 to 50 shots', NULL, NULL, NULL, NULL, 'High-capacity rifle magazine, similar to CS canisters and usable in Coalition weapons. It is bulky, with a -1 to strike penalty.', 'Rifts World Book 8: Japan p.117'),
('vibro-knife-tanto-jitte-sai', 'Vibro-Knife / Tanto / Jitte / Sai', 'rifts', 'weapon', NULL, 7000, '7000 cr; ArmaTech often commands +20% over the listed prices', '1D6 M.D.', 1, 'melee', NULL, NULL, NULL, NULL, NULL, 'Blade in a high-frequency energy field, made by both ArmaTech and H-Brand. The price covers the four blade types.', 'Rifts World Book 8: Japan p.117'),
('vibro-bayonet', 'Vibro-Bayonet', 'rifts', 'weapon', NULL, 7500, '7500 cr', '1D6+1 M.D.', 1, 'melee', NULL, NULL, NULL, NULL, NULL, 'Bayonet for attachment to a variety of rifles, including the AT-18.', 'Rifts World Book 8: Japan p.117'),
('vibro-saber-short-sword-ninja-short-sword', 'Vibro-Saber / Short Sword / Ninja Short Sword', 'rifts', 'weapon', NULL, 9000, '9000 cr', '2D4 M.D.', 1, 'melee', NULL, NULL, NULL, NULL, NULL, 'Short sword in a vibro field.', 'Rifts World Book 8: Japan p.117'),
('vibro-sword-large-one-handed-sword-straight', 'Vibro-Sword / Large One-Handed Sword (straight)', 'rifts', 'weapon', NULL, 11000, '11,000 cr', '2D6 M.D.', 1, 'melee', NULL, NULL, NULL, NULL, NULL, 'Straight one-handed vibro sword.', 'Rifts World Book 8: Japan p.117'),
('vibro-wakizashi', 'Vibro-Wakizashi', 'rifts', 'weapon', NULL, 11000, '11,000 cr', '2D6 M.D.', 1, 'melee', NULL, NULL, NULL, NULL, NULL, 'Curved samurai short sword with a vibro field.', 'Rifts World Book 8: Japan p.117'),
('vibro-katana', 'Vibro-Katana', 'rifts', 'weapon', NULL, 15000, '15,000 cr', '3D6 M.D.', 1, 'melee', NULL, NULL, NULL, NULL, NULL, 'Curved samurai long sword with a vibro field.', 'Rifts World Book 8: Japan p.117'),
('vibro-robot-sword', 'Vibro-Robot Sword', 'rifts', 'weapon', NULL, 25000, '25,000 cr; military use only', '4D6 M.D.', 1, 'melee', NULL, NULL, NULL, NULL, NULL, 'Giant-size vibro sword for robots and large power armor.', 'Rifts World Book 8: Japan p.117'),
('vibro-no-dachi-large-two-handed-swords-h-brand', 'Vibro-No-Dachi / Large Two-Handed Swords (H-Brand)', 'rifts', 'weapon', NULL, 15000, '15,000 cr; H-Brand exclusive, illegal in the Republic', '3D6 M.D.', 1, 'melee', NULL, NULL, NULL, NULL, NULL, 'Two-handed vibro sword made only by H-Brand.', 'Rifts World Book 8: Japan p.117'),
('vibro-kusari-gama', 'Vibro-Kusari-Gama', 'rifts', 'weapon', NULL, 10000, '10,000 cr; H-Brand special, illegal in the Republic', '2D6 M.D. blade; chain and weighted end 1D6 S.D.C.', 1, 'melee', NULL, NULL, NULL, NULL, NULL, 'Sickle-and-chain weapon. The chain and weight are plain S.D.C. and are sometimes silver coated.', 'Rifts World Book 8: Japan p.117'),
('vibro-yari-spear', 'Vibro-Yari Spear', 'rifts', 'weapon', NULL, 10000, '10,000 cr; H-Brand special, illegal in the Republic', '2D6 M.D.', 1, 'melee', NULL, NULL, NULL, NULL, NULL, 'Vibro spear sold by H-Brand.', 'Rifts World Book 8: Japan p.117'),
('vibro-naginata-bisento', 'Vibro-Naginata / Bisento', 'rifts', 'weapon', NULL, 15000, '15,000 cr; H-Brand special, illegal in the Republic', '3D6 M.D.', 1, 'melee', NULL, NULL, NULL, NULL, NULL, 'Curved-blade or broad-blade vibro polearm.', 'Rifts World Book 8: Japan p.117'),
('vibro-arm-claws', 'Vibro-Arm Claws', 'rifts', 'weapon', NULL, 11000, '11,000 cr; +2000 if retractable; H-Brand special', '2D6 M.D.', 1, 'melee', NULL, NULL, NULL, NULL, NULL, 'Usually three hooked blades on a forearm gauntlet or plate; good for parrying and slashing.', 'Rifts World Book 8: Japan p.117'),
('vibro-tiger-claws-bagh-nakh', 'Vibro-Tiger Claws / Bagh Nakh', 'rifts', 'weapon', NULL, 5000, '5000 cr; H-Brand special', '1D4 M.D.', 1, 'melee', NULL, NULL, NULL, NULL, NULL, 'Hand-held claws with three curved spikes, used for climbing M.D.C. structures or slashing.', 'Rifts World Book 8: Japan p.117'),
('exploding-shuriken-throwing-spike', 'Exploding Shuriken / Throwing Spike', 'rifts', 'weapon', NULL, 50, '50 cr each', '4D6 S.D.C.', 0, 'thrown', NULL, NULL, NULL, NULL, NULL, 'Throwing spike whose high-frequency energy field is switched on and off by a small radio transmitter. A radio transmitter comes with every three.', 'Rifts World Book 8: Japan p.118'),
('at-n20-neural-stick', 'AT-N20 Neural Stick', 'rifts', 'weapon', NULL, NULL, 'no price printed', 'Club: 1D6 S.D.C. + P.S. bonus. Stun: save vs non-lethal 16+; success loses 1 melee action, failure gives -7 initiative and -5 to strike/parry/dodge, half actions and speed, 2D4 rounds (+2D4 per extra hit); 15% cumulative knockout chance for 1D4 minutes', 0, 'melee', NULL, NULL, NULL, NULL, 17, 'ArmaTech police nightstick-style stun club that delivers a nerve-shorting electric jolt. It is a mega-damage structure (17 M.D.C.) usable for parrying. Ineffective against environmental armor, power armor and full-conversion borgs.', 'Rifts World Book 8: Japan p.120'),
('at-aad-anti-armor-dissolver-missile-or-grenade', 'AT-AAD Anti-Armor Dissolver Missile or Grenade', 'rifts', 'weapon', 1, NULL, 'no price; NOT on the Black Market, Republic military only', 'Special: nano-bots cut the target''s M.D.C. by 50% (body armor, light power armor), 30% (heavy power armor, light vehicles) or 10% (heavy robots, tanks) within about 4 melee rounds, then destroy one system in 1D4x10 minutes (d% table: main weapon, sensors, a limb, head/hatch, two secondary weapons)', 0, 'Hand grenade about 100 ft; rifle grenade/rocket about 300 ft; mini-missile 1 mile, usually launched at 3000 ft', 'One AAD package per grenade or missile; elite troops carry 1-6', 'Usually one at a time or volleys of 3 mini-missiles; not available in large missiles', NULL, NULL, NULL, 'Nano-bot payload that dissolves mega-damage armor on a molecular level. The bots live 50 minutes and attack only the first armor they touch, military alloys only. Carefully guarded Republic secret. A grenade weighs 1 lb, a mini-missile 8 lbs.', 'Rifts World Book 8: Japan p.120'),
('at-23-plasma-thrower', 'AT-23 Plasma Thrower', 'rifts', 'weapon', 15, 20000, '20,000 cr; military only in the Republic; H-Brand makes a knock-off', '1D4x10 M.D. per spray', 1, '200 ft (61 m)', '8 sprays per plasma canister', 'Aimed shots only', NULL, NULL, NULL, 'ArmaTech modernized flame-thrower that shoots short plasma streams, revived as a tool against fire-vulnerable supernatural threats.', 'Rifts World Book 8: Japan p.121'),
('at-6-mini-laser-pistol-escape-artist', 'AT-6 Mini Laser Pistol (Escape Artist)', 'rifts', 'weapon', 1, 30000, '30,000 cr market; 50,000 on Black Market; 5000 per mini-E-clip', '1D6 M.D.', 1, '300 ft (91.4 m)', '6 blasts; needs a special mini E-clip', 'Standard', NULL, NULL, NULL, 'ArmaTech palm-sized pistol shaped like a cigarette lighter or pen flashlight, for concealment (+10% to palming and concealment). Military only, with no H-Brand copies.', 'Rifts World Book 8: Japan p.121'),
('at-8-laser-pistol', 'AT-8 Laser Pistol', 'rifts', 'weapon', 3, 10000, '10,000 cr market; 8500 on Black Market; good availability in and out of the Republic', '1D6 M.D.', 1, '500 ft (152 m)', '8 shots', 'Standard', NULL, NULL, NULL, 'Light ArmaTech pistol, one of the few mega-damage weapons sold to civilians; registration is required and sales are limited to corporate security, executives and similar buyers. It is reliable but low in payload and stopping power.', 'Rifts World Book 8: Japan p.121'),
('h-8-laser-pistol-h-brand', 'H-8 Laser Pistol (H-Brand)', 'rifts', 'weapon', 3, 8000, '8000 cr', '1D6 M.D.', 1, '500 ft', '8 shots', 'Standard', NULL, NULL, NULL, 'H-Brand knock-off identical to the AT-8.', 'Rifts World Book 8: Japan p.122'),
('super-h-8-laser-pistol-h-brand', 'Super H-8 Laser Pistol (H-Brand)', 'rifts', 'weapon', NULL, 11000, '11,000 cr', '1D6 M.D.', 1, '800 ft (224 m)', '12-shot E-clip', 'Standard', NULL, NULL, NULL, 'H-Brand upgrade of the H-8 with a bigger clip and longer range.', 'Rifts World Book 8: Japan p.122'),
('at-20-sharpshot-police-special-laser-pistol', 'AT-20 Sharpshot Police Special Laser Pistol', 'rifts', 'weapon', 2, 15000, '15,000 cr market; 22,000 on Black Market; military, police and authorized corporate security only', '2D6 M.D.', 1, '1000 ft (305 m)', '20 shots', 'Aimed shots and short bursts (4 blasts) only', NULL, NULL, NULL, 'Heavy ArmaTech laser pistol with telescopic sight mounts, laser targeting and long-range accuracy. +1 to strike on an aimed shot.', 'Rifts World Book 8: Japan p.122'),
('h-20-sniper-pistol-h-brand', 'H-20 Sniper Pistol (H-Brand)', 'rifts', 'weapon', NULL, 17000, '17,000 cr; poor availability in Republic, fair to good outside', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, 'H-Brand copy of the AT-20.', 'Rifts World Book 8: Japan p.122'),
('at-30-combat-laser-pistol', 'AT-30 Combat Laser Pistol', 'rifts', 'weapon', 2.5, 22000, '22,000 cr market; 30,000 on Black Market (rarely available); military and elite police only', '2D6+2 M.D.', 1, '1000 ft (305 m)', '30-shot clip', 'Standard', NULL, NULL, NULL, 'Official sidearm of the Republic Armed Forces, with a longer barrel, two extra E-clips, sight mounts and laser targeting. +1 to strike on an aimed shot.', 'Rifts World Book 8: Japan p.122'),
('h-30-siege-pistol-h-brand', 'H-30 Siege Pistol (H-Brand)', 'rifts', 'weapon', NULL, 35000, '35,000 cr; poor availability in Republic, fair outside', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, 'H-Brand copy of the AT-30.', 'Rifts World Book 8: Japan p.122'),
('at-130-particle-beam-pistol', 'AT-130 Particle Beam Pistol', 'rifts', 'weapon', 4, 30000, '30,000 cr; limited military availability; 90,000+ on the Black Market', '5D6+6 M.D. per single blast', 1, '600 ft (183 m)', '10 shots per E-clip', 'Standard; single shot only', NULL, NULL, NULL, 'ArmaTech particle-beam pistol, a pre-Rifts design exclusive to high-ranking officers and espionage agents. Comes with two extra E-clips, sight mounts and laser targeting; +1 to strike on an aimed shot. H-Brand cannot copy it.', 'Rifts World Book 8: Japan p.122'),
('h-10-combat-laser-pistol', 'H-10 Combat Laser Pistol', 'rifts', 'weapon', 4.5, 12000, '12,000 cr, good availability', '2D4 M.D.', 1, '600 ft (183 m)', '30 blasts (standard E-clip)', 'Standard', NULL, NULL, 23, 'Cheap, large, archaic H-Brand laser pistol with light stopping power, popular with adventurers, bandits and thugs.', 'Rifts World Book 8: Japan p.123'),
('h-13-ion-pulse-pistol', 'H-13 Ion Pulse Pistol', 'rifts', 'weapon', 5, 22000, '22,000 cr; poor availability in the Republic, good elsewhere', '2D6 M.D. single shot; 6D6 M.D. per pulse burst (three nearly simultaneous shots)', 1, '800 ft (244 m)', '20 shots', 'Standard', NULL, NULL, NULL, 'Heavy H-Brand pistol resembling a pre-Rifts sub-machinegun, refused by most kingdoms for military use but popular with adventurers.', 'Rifts World Book 8: Japan p.123'),
('at-23-police-stun-rifle', 'AT-23 Police Stun Rifle', 'rifts', 'weapon', 8, 25000, '25,000 credits; 35,000 on the Black Market, fairly rare; police and military only', 'Five settings: 1) 1D6 S.D.C., 2) 2D6 S.D.C., 3) 3D6 S.D.C., 4) 6D6 S.D.C., 5) 1D6 M.D. Stun: save vs non-lethal 16+ (18+ for children and small animals); failure gives -9 initiative and -7 strike/parry/dodge, half actions and speed, 2D4 rounds (+2D4 per extra blast); 15% cumulative knockout chance. Saves get +4 per level the setting is too low', 1, '800 ft (244 m)', '20 shots per standard E-clip', 'Single shot; semi-automatic', NULL, NULL, NULL, 'Standard issue non-lethal police rifle with adjustable stun settings, a telescopic passive nightvision scope and laser targeting. Ineffective against environmental armor, power armor and full-conversion borgs. Available only to police and military; no H-Brand copy.', 'Rifts World Book 8: Japan p.123'),
('at-84-sharpshot-laser-rifle', 'AT-84 Sharpshot Laser Rifle', 'rifts', 'weapon', 6, 20000, '20,000 cr market; 34,000 on Black Market; military, police and authorized corporate security only', 'Light 2D6 M.D. or heavy 4D6 M.D.', 1, '3000 ft (914 m)', '30 light shots; each heavy blast counts as two', 'Standard', NULL, NULL, NULL, 'Sleek, accurate ArmaTech rifle used by police, military and security; a favorite of assassins and snipers. +1 to strike on an aimed shot.', 'Rifts World Book 8: Japan p.124'),
('h-84-sniper-rifle-h-brand', 'H-84 Sniper Rifle (H-Brand)', 'rifts', 'weapon', NULL, 29000, '29,000 cr; poor availability in Republic, fair to good outside', '3D6 M.D., one setting', 1, '2000 ft (610 m)', NULL, NULL, NULL, NULL, NULL, 'H-Brand copy of the AT-84 with a single setting and reduced range.', 'Rifts World Book 8: Japan p.124'),
('at-88-combat-laser-rifle', 'AT-88 Combat Laser Rifle', 'rifts', 'weapon', 9, 30000, '30,000 cr market; 54,000 on Black Market (rare); military and elite police only; no H-Brand copy', 'Laser 3D6 M.D.; grenade launcher: 4D6 M.D. fragmentation, 5D6 HE/AP, smoke or AAD-Dissolver', 1, '3000 ft (914 m)', 'Laser: 30 shots per E-clip or 100 per E-canister; grenades: 3, reloaded by hand at one melee action each', 'Standard', NULL, NULL, NULL, 'Standard issue rifle of the Republic Armed Forces, accurate, with an underbarrel pump-action grenade launcher.', 'Rifts World Book 8: Japan p.125'),
('at-230-particle-beam-rifle', 'AT-230 Particle Beam Rifle', 'rifts', 'weapon', 11, 45000, '45,000 cr; limited military availability; 150,000+ on Black Market', '1D4x10+10 M.D. per single blast', 1, '1300 ft (395 m)', '10 shots per standard E-clip; 50 from an energy canister', 'Standard; semi-automatic', NULL, NULL, NULL, 'Compact, durable particle-beam rifle issued to elite power armor troops, SAMAS, elite borgs and Special Forces; one of the most powerful rifles on Earth. No H-Brand copy.', 'Rifts World Book 8: Japan p.125'),
('atu-80-underwater-assault-rifle', 'ATU-80 Underwater Assault Rifle', 'rifts', 'weapon', 8, 25000, '25,000 cr market; 30,000 on Black Market; military, police and authorized corporate security only', 'Laser three settings: 6D6 S.D.C., 2D6 M.D., 4D6 M.D. (4D6 uses two blasts of payload). Spear launcher: vibro-spear 1D6 M.D.; conventional spear 2D6 S.D.C.', 1, 'Laser 2000 ft (610 m) underwater or in air; spears 400 ft (122 m)', '30 shots per E-clip or 100 per energy canister; spear launcher 1 shot, 1 melee action to reload', 'Standard', NULL, NULL, NULL, 'Standard weapon of the Republic''s tiny navy, combining a laser rifle with a spear/harpoon launcher, usable on land and underwater. No H-Brand version.', 'Rifts World Book 8: Japan p.125'),
('h-12-defender-ion-pulse-rifle', 'H-12 Defender Ion Pulse Rifle', 'rifts', 'weapon', 9, 26000, '26,000 cr, good availability; illegal in the Republic', '2D6 M.D. single shot; 6D6 M.D. per pulse burst (three simultaneous shots)', 1, '1600 ft (488 m)', '30 shots per standard E-clip', 'Standard', NULL, NULL, NULL, 'H-Brand ion pulse rifle that can fire single blasts or three-shot pulses, popular with adventurers, bandits and mercenaries.', 'Rifts World Book 8: Japan p.126'),
('h-15-scattergun-shotgun', 'H-15 Scattergun Shotgun', 'rifts', 'weapon', 9, 20000, '20,000 cr, good availability; illegal in the Republic', '4D6 M.D.', 1, '500 ft (152 m) standard; 200 ft (61 m) sawed-off', '2 shots (25 mm M.D. shotshell); two melee actions to reload', 'Standard; see Modern Weapon Proficiency Section', NULL, NULL, NULL, 'H-Brand modern shotgun firing 25 mm M.D. shotshells of explosive pellets with short range. Double-barrelled and sawed-off versions are popular among urban criminals.', 'Rifts World Book 8: Japan p.126'),
('at-600-rail-gun', 'AT-600 Rail Gun', 'rifts', 'weapon', 48, 65000, '65,000 cr; limited military availability; 100,000+ on Black Market', '6D6 M.D. per 30-round burst', 1, '3000 ft (914 m)', 'Short clip 300 rounds (10 bursts); light drum 600 (20 bursts); heavy drum 2400 (80 bursts)', 'Bursts and wild only', NULL, NULL, NULL, 'Lighter squad-support rail gun usable by anyone with P.S. 20+, though usually a two-man weapon because of the ammo container. Best on vehicles, bunkers, cyborgs or power armor.', 'Rifts World Book 8: Japan p.127'),
('at-1200-super-rail-gun', 'AT-1200 Super Rail Gun', 'rifts', 'weapon', 228, 80000, '80,000 cr; limited military availability; 150,000+ on Black Market', '1D6x10 M.D. per 40-round burst; one round 1D6 M.D.', 1, '4000 ft (1220 m)', 'Clip 400 rounds (10 bursts); AT-1200 drum 4000 rounds (100 bursts)', 'Standard; bursts, spray or wild', NULL, NULL, NULL, 'Larger AT-600 built for power armor, robots and heavy cyborgs, firing heavier rounds. Needs P.S. 28+ to carry or fire.', 'Rifts World Book 8: Japan p.127'),
('h-600-rail-gun', 'H-600 Rail Gun', 'rifts', 'weapon', 100, 65000, '65,000 cr; poor to fair availability; illegal in the Republic and rare even among criminals', '1D4x10 M.D. per 40-round burst', 1, '4000 ft (1220 m)', 'Light drum 800 rounds (20 bursts); heavy drum 2400 rounds (60 bursts)', 'Standard; bursts, spray or wild', NULL, NULL, NULL, 'H-Brand tripod-mounted rail gun needing a combined P.S. of 25, best for augmented humans, power armor, borgs and robots.', 'Rifts World Book 8: Japan p.128'),
('arc-2-nighthawk-defense-system', 'ARC-2 Nighthawk Defense System', 'rifts', 'weapon', 187, 180000, '180,000 cr; limited military availability; not on Black Market', '1D6x10 M.D. per 60-round burst', 1, '2000 ft (610 m) limited by sensors; the rail gun can fire to 4000 ft (1220 m)', 'Power/ammo pack holds 6000 rounds (100 bursts); reload 10 minutes by technicians', 'Bursts only, up to four per melee round', NULL, NULL, NULL, 'Automated tripod-mounted gatling rail gun sentry with radar or thermo-imaging, that identifies intruders by heat signature and fires on the nearest. It rotates 180 degrees horizontally and 30 degrees vertically, and can be deactivated by coded radio.', 'Rifts World Book 8: Japan p.128'),
('mini-concussion-missile', 'Mini-Concussion Missile', 'rifts', 'weapon', NULL, 4000, '4000 cr, poor availability', '5D6 M.D., blast radius 30 ft (9.1 m)', 1, '2000 ft (610 m)', NULL, NULL, NULL, NULL, NULL, 'Knock-out style concussion missile (01-88% knocked off feet, 01-65% stunned).', 'Rifts World Book 8: Japan p.129'),
('short-concussion-missile', 'Short Concussion Missile', 'rifts', 'weapon', NULL, 8500, '8500 cr, poor availability', '1D6x10 M.D., blast radius 60 ft (18.3 m)', 1, '6000 ft (1830 m)', NULL, NULL, NULL, NULL, NULL, 'Short-range concussion missile.', 'Rifts World Book 8: Japan p.129'),
('medium-concussion-missile', 'Medium Concussion Missile', 'rifts', 'weapon', NULL, 11000, '11,000 cr, poor availability', '2D4x10 M.D., blast radius 90 ft (27.4 m)', 1, '6000 ft (1830 m)', NULL, NULL, NULL, NULL, NULL, 'Medium concussion missile.', 'Rifts World Book 8: Japan p.129'),
('heavy-concussion-missile', 'Heavy Concussion Missile', 'rifts', 'weapon', NULL, 20000, '20,000 cr, poor availability', '3D4x10 M.D., blast radius 120 ft (36.5 m)', 1, '2 miles (3.2 km)', NULL, NULL, NULL, NULL, NULL, 'Heavy concussion missile.', 'Rifts World Book 8: Japan p.129'),
('mini-hh-heavy-hitter-missile', 'Mini-HH (Heavy-Hitter) Missile', 'rifts', 'weapon', NULL, 5000, '5000 cr', '1D6x10 M.D.', 1, '1/2 mile (0.8 km)', NULL, NULL, NULL, NULL, NULL, 'HE missile carrying the warhead of the next size up, so more damage but much shorter range.', 'Rifts World Book 8: Japan p.129'),
