('at-d50-anti-personnel-mine', 'AT-D50 Anti-Personnel Mine', 'rifts', 'weapon', 12, 4500, '4500 cr Black Market; fair availability', '6D6 M.D., 12 ft (3.65 m) blast area', 1, NULL, NULL, NULL, NULL, NULL, 15, 'Simple platter charge triggered by 200 lbs of pressure (30 lbs on a trip wire). Casing M.D.C. 15; -5% camouflage due to bulk.', 'Rifts World Book 8: Japan p.131'),
('at-d52-bullet-anti-personnel-mine', 'AT-D52 Bullet Anti-Personnel Mine', 'rifts', 'weapon', 1, 500, '500 cr Black Market; poor to fair availability', '4D6 M.D., 1 ft (0.3 m) blast area', 1, NULL, NULL, NULL, NULL, 20, NULL, 'Tiny plastic-cased mine (3 in long) containing an AT-25 grenade round atop a steel pin; footfall fires it. -30% to detect; +15% to camouflage.', 'Rifts World Book 8: Japan p.131'),
('at-d54-anti-armor-mine', 'AT-D54 Anti-Armor Mine', 'rifts', 'weapon', 45, 18000, '18,000 cr Black Market; fair availability', '2D6x10 M.D., 15 ft (4.5 m) blast area', 1, NULL, NULL, NULL, NULL, NULL, 5, 'Large platter mine set off by 500 lbs of pressure. Casing M.D.C. 5; -25% to camouflage.', 'Rifts World Book 8: Japan p.131'),
('cosmetic-implants', 'Cosmetic Implants', 'rifts', 'cybernetics', NULL, 2000, 'Varies; typically 2,000 to 8,000 credits.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Implants that reshape the nose, ears, chin, cheeks or breasts and can shift between two or three shapes; not enough for a real disguise.', 'Rifts World Book 8: Japan p.109'),
('computer-virus-carrier', 'Computer Virus Carrier', 'rifts', 'cybernetics', NULL, 41000, 'Typically 41,000 to 65,000 credits. Illegal.', NULL, 0, NULL, 'up to 6 viruses', NULL, NULL, NULL, NULL, 'Carries up to six viruses into a computer through a jack: 71% success on civilian systems, 10% corporate, 1% police or state of the art, useless against military; hacking time -33%. Illegal in the Republic of Japan: fines, a criminal record and removal at the owner''s cost; prison for repeat or criminal use (printed 109).', 'Rifts World Book 8: Japan p.109'),
('computer-hacker-encoder', 'Computer Hacker Encoder', 'rifts', 'cybernetics', NULL, 41000, 'Typically 41,000 to 65,000 credits. Illegal.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Code-breaking programs run through any computer jack: 93% success on civilian systems, 50% corporate, 7% police or state of the art, 2% military; hacking time -33%. Illegal in the Republic of Japan: fines, a criminal record and removal at the owner''s cost; prison for repeat or criminal use (printed 109).', 'Rifts World Book 8: Japan p.109-110'),
('computerized-telephone-jack', 'Computerized Telephone Jack', 'rifts', 'cybernetics', NULL, 500, '500 credits. Illegal.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Free use of public phones, lines and fax; the call is traced within 1D4 minutes. Penalty: a 500 credit fine, a criminal record and removal.', 'Rifts World Book 8: Japan p.110'),
('cyberware-networking', 'Cyberware Networking', 'rifts', 'cybernetics', NULL, 75000, '75,000 credits.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Eavesdrops on another person''s cybernetics, bionics and radio through a computer jack, up to three people, by physical connection; it cannot control them.', 'Rifts World Book 8: Japan p.110'),
('cyber-drone', 'Cyber-Drone', 'rifts', 'cybernetics', NULL, 500000, 'Half a million credits or more; extremely rare. Highly illegal: 20 to 40 years without parole, possibly death.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'As cyberware networking, but it seizes control of the victim''s cybernetics and bionics (not his biology). Made by tech-ninjas.', 'Rifts World Book 8: Japan p.110'),
('data-chip', 'Data Chip', 'rifts', 'cybernetics', NULL, 26000, '26,000 credits. Illegal.', NULL, 0, NULL, '1 meg', NULL, NULL, NULL, NULL, 'A 1-meg chip on the brain''s surface, read through an optic nerve video implant, HUD visor or networking; one at a time (two cost -30% to skills, -4 to bonuses and risk madness); psionic range and duration -10%. Penalty: a 1,500 credit fine, a criminal record and removal.', 'Rifts World Book 8: Japan p.110'),
('depth-gauge-cybernetic', 'Depth Gauge (Cybernetic)', 'rifts', 'cybernetics', NULL, 600, '600 credits for the cheap vibrating model; 4,000 for the standard one.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Measures depth and pressure; the standard model pings for every foot, states the depth every 10 ft and warns of danger.', 'Rifts World Book 8: Japan p.110'),
('metal-detector-cybernetic', 'Metal Detector (Cybernetic)', 'rifts', 'cybernetics', NULL, 4500, '4,500 credits.', NULL, 0, '2 ft (0.6 m)', NULL, NULL, NULL, NULL, NULL, 'A detector in the hand or forearm that finds metal and bionics within 2 ft; only a 10% chance to sense metal under flesh.', 'Rifts World Book 8: Japan p.110'),
('power-booster', 'Power Booster', 'rifts', 'cybernetics', NULL, 25000, '25,000 credits. Illegal.', NULL, 0, NULL, '20 energy blasts', NULL, NULL, NULL, NULL, 'A mini E-clip backup power source for cybernetic tools and weapons, good for 20 energy blasts.', 'Rifts World Book 8: Japan p.110'),
