('signal-booster', 'Signal Booster', 'rifts', 'cybernetics', NULL, 1200, '1,200 credits.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Boosts communication and computer implants: clearer sound and +25% range.', 'Rifts World Book 8: Japan p.110'),
