('chest-blaster', 'Chest Blaster', 'rifts', 'cybernetics', NULL, 24000, '24,000 credits.', '3D6 M.D.', 1, '800 ft (244 m)', '20 shots; recharges in 4 hours', 'equal to the hand to hand attacks', NULL, NULL, NULL, 'A laser on a mini-turret in a bionic chest, aiming through 45 degrees; up to three can be mounted. 20 shots, recharged in 4 hours, or unlimited on an internal energy supply. A bionic system: only for partial or full conversion cyborgs (printed 111).', 'Rifts World Book 8: Japan p.111'),
('internal-energy-supply', 'Internal Energy Supply', 'rifts', 'cybernetics', NULL, 500000, '500,000 credits electric battery; 1,000,000 nuclear.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Powers forearm blasters, palm energy generators, chest blasters and palm weapon links: a battery gives 500 blasts, a nuclear supply about 11 years of unlimited fire. A bionic system: only for partial or full conversion cyborgs (printed 111).', 'Rifts World Book 8: Japan p.111'),
('internal-ammo-drum', 'Internal Ammo Drum', 'rifts', 'cybernetics', NULL, 5000, '5,000 credits.', NULL, 0, NULL, '3,000 rounds', NULL, NULL, NULL, NULL, 'A spring-loaded compartment holding 3,000 rounds of belted rail gun ammunition for standard ArmaTech weapons. A bionic system: only for partial or full conversion cyborgs (printed 111).', 'Rifts World Book 8: Japan p.111'),
